B.bSr=new A.jD("Breaker off, then test","Before you touch any wire, switch its breaker OFF, then check with a voltage tester that the wire is dead. A switch on the wall is not enough.")
B.bSe=new A.jD("Lock out, tag out","On a real job you put a lock or a note on the panel so nobody switches the power back on while you work.")
B.bSy=new A.jD("Water and power","Water carries electricity. Near sinks, tubs and outdoors the outlets must be GFCI, and wet hands never touch wires.")
B.bSj=new A.jD("Eyes, ears, lungs","Safety glasses for drilling and cutting, ear protection for loud tools, and a mask when you sand drywall dust or cut tile.")
B.bSx=new A.jD("Shut the water off","Before you cut or loosen a pipe, close the main water valve and open a faucet to drain the line.")
B.d7T=w([B.bSr,B.bSe,B.bSy,B.bSj,B.bSx],x.Z)
B.bSK=new A.Mm("Safety first","\ud83e\uddba",D.cf,B.d7T)
B.bSz=new A.jD("Wire colours","Black is hot (it carries the power), white is neutral (the way back), bare copper or green is ground (the safety path). Red is a second hot, often used for a switched line.")
B.bSG=new A.jD("Screw colours","On an outlet the brass screw takes the hot wire, the silver screw takes the neutral and the green screw takes the ground.")
B.bSt=new A.jD("Wire size","14 gauge wire is for 15 amp circuits (lights and outlets). 12 gauge is for 20 amp circuits (kitchens). A thinner wire than the breaker allows can overheat and start a fire.")
B.bSn=new A.jD("Breakers","A breaker is a safety switch. It trips when a circuit carries too much current, so the wires never get hot enough to burn.")
B.bSB=new A.jD("Wire nuts","Strip about 3/4 inch, twist the bare ends together clockwise, and screw on the nut until no bare copper shows. Give each wire a gentle tug.")
B.bSH=new A.jD("Switches","A switch cuts the hot wire only. The neutral goes straight through to the light.")
B.bSI=new A.jD("GFCI","A GFCI outlet watches the current going out and coming back. If a little leaks (through water or a person) it cuts the power in a fraction of a second.")
B.bSg=new A.jD("Ceiling fans","A fan shakes and is heavy. It needs a box that says fan rated, fixed to the joist, not a plain light box.")
B.bSi=new A.jD("Heights","Outlets sit about 16 inches from the floor. Switches sit about 48 inches up, where your hand falls.")
B.d0F=w([B.bSz,B.bSG,B.bSt,B.bSn,B.bSB,B.bSH,B.bSI,B.bSg,B.bSi],x.Z)
B.bSN=new A.Mm("Wiring basics","\u26a1",D.cd,B.d0F)
B.bSf=new A.jD("Hot left, cold right","On a faucet, hot is on the left and cold on the right. Hot lines are marked red and cold lines blue.")
B.bSs=new A.jD("The P-trap","The curved pipe under a sink always holds a little water. That water seal stops sewer gas coming up the drain.")
B.bSD=new A.jD("Shut-off valves","Every sink and toilet has its own small valve, so you can stop the water to one fixture without turning off the whole house.")
B.bSl=new A.jD("Slip nuts","Drain joints are sealed by a washer and a slip nut. Tighten by hand and a quarter turn: too much force cracks plastic.")
B.bSk=new A.jD("Wax ring","A toilet sits on a wax ring that seals it to the floor drain. A toilet is lowered straight down once, and cannot be slid around.")
B.bSA=new A.jD("Drain slope","Drains fall about 1/4 inch per foot so water and waste keep moving. Too flat and it clogs, too steep and the water leaves the solids behind.")
B.bSF=new A.jD("Order of work","Plumbing goes from the top down on the drain (tailpiece, trap, arm) and from the wall out on the supply (valve, hose, fixture).")
B.c9l=w([B.bSf,B.bSs,B.bSD,B.bSl,B.bSk,B.bSA,B.bSF],x.Z)
B.bSL=new A.Mm("Plumbing basics","\ud83d\udeb0",D.cr,B.c9l)
B.bSh=new A.jD("Studs","Studs are the vertical 2x4 posts inside a wall, 16 inches apart from centre to centre. Everything is fixed to them.")
B.bSv=new A.jD("Drilling studs","Holes for cable go through the middle of the stud, so a nail or screw cannot reach the wire.")
B.bSm=new A.jD("Drywall","A sheet is 4 feet wide, so its edges land on studs 48 inches apart. Screws go into studs only, just under the paper.")
B.bSp=new A.jD("Taping and mud","Seams get paper tape and three thin coats of joint compound, sanded smooth between coats, then primer and paint.")
B.bSE=new A.jD("Order of a build","Frame, run the pipes and wires (rough-in), inspect, hang drywall, finish it, paint, then fit the fixtures and devices.")
B.cNo=w([B.bSh,B.bSv,B.bSm,B.bSp,B.bSE],x.Z)
B.bSJ=new A.Mm("Framing and walls","\ud83c\udfe0",D.dT,B.cNo)
B.bSq=new A.jD("Voltage tester","A pen that glows or beeps near live wires. Test it on a known live outlet first, so you know it works.")
B.bSw=new A.jD("Wire strippers","Strip the plastic off without nicking the copper. A nick weakens the wire.")
B.bSC=new A.jD("Adjustable wrench","For nuts on valves and hoses. Hold the fitting steady with a second wrench so you do not twist the pipe.")
B.bSu=new A.jD("Drill and screw gun","A drill makes holes through studs. A screw gun sets drywall screws to the right depth.")
B.bSo=new A.jD("Level and tape measure","Measure twice, cut once. A level makes sure outlets, shelves and pipes are straight.")
B.dfu=w([B.bSq,B.bSw,B.bSC,B.bSu,B.bSo],x.Z)
